mapper.insert:

    SELECT
        'SLRY'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(SALARY_ID), LENGTH('SLRY' ) + 1)), 0) + 1, 6, '0')
    FROM SALARY

INSERT INTO SALARY (
		SALARY_ID
		, USER_ID
		, CODE_DETAIL_NO
		, SALARY_MIN
		, SALARY_MAX
		, CREATE_DATE
	) VALUES (
	#{salaryId}
		, #{userId}
		, #{codeDetailNo}
		, #{salaryMin}
		, #{salaryMax}
		, SYSDATE
)
